<?php
namespace App\Foundation\Console;use App\Foundation\Registry\ProjectRegistry;use Illuminate\Console\Command;
final class PageCheckCommand extends Command{protected $signature='page:check';protected $description='Validate page manifests, surfaces and view targets.';public function handle(ProjectRegistry $r):int{$surfaces=array_column($r->surfaces(),'name');$templates=array_map(fn($d)=>$d['name'],array_filter($r->design(),fn($d)=>($d['type']??'')==='template'));$bad=false;foreach($r->pages() as $p){if(!in_array($p['surface']??'',$surfaces,true)){$this->error($p['name'].': missing surface');$bad=true;}$view=$p['handler']['target']??'';$file=resource_path('views/'.str_replace('.','/',$view).'.blade.php');if(!is_file($file)){$this->error($p['name'].': missing view '.$view);$bad=true;}if(($p['template']??null)&&!in_array($p['template'],$templates,true)){$this->error($p['name'].': missing design template '.$p['template']);$bad=true;}}if(!$bad)$this->info('Pages valid.');return $bad?self::FAILURE:self::SUCCESS;}}
